import pyomo.environ as pyo

DATA = {
    "probes_per_test": {"salinity": 3, "pH": 2},
    "min_pH_tests": 250,
    "min_total_tests": 400,
    "max_pH_to_salinity_ratio": 1.5,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.TESTS = pyo.Set(initialize=list(d["probes_per_test"].keys()))

    model.tests = pyo.Var(model.TESTS, within=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return sum(d["probes_per_test"][t] * m.tests[t] for t in m.TESTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def min_pH_rule(m):
        return m.tests["pH"] >= d["min_pH_tests"]

    model.min_pH = pyo.Constraint(rule=min_pH_rule)

    def min_total_rule(m):
        return sum(m.tests[t] for t in m.TESTS) >= d["min_total_tests"]

    model.min_total = pyo.Constraint(rule=min_total_rule)

    def ratio_rule(m):
        return m.tests["pH"] <= d["max_pH_to_salinity_ratio"] * m.tests["salinity"]

    model.ratio = pyo.Constraint(rule=ratio_rule)

    return model


